(() => {
  'use strict';
  const canvas = document.getElementById('scene');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const memories = [
    { id:'regret', name:'Regret', x:4.7, y:13.6, title:'The room of almost', kicker:'A MEMORY OF REGRET', color:'#9a684b', note:'A letter folded until the paper became soft as cloth.\n\nShe never sent it. Years later, the words were still warm in her hands: not an apology, exactly, but the shape of one. In the margin, a child had drawn a door with no handle.', flash:'I should have said something.' },
    { id:'fear', name:'Fear', x:20.3, y:4.7, title:'The room that listens', kicker:'A MEMORY OF FEAR', color:'#8b9290', note:'Every night, the pipes spoke in the walls. Her father called it the house settling. She learned to count the seconds between each sound, and to keep her shoes beside the bed.', flash:'There is nowhere to hide from a sound.' },
    { id:'desire', name:'Longing', x:13.9, y:11.2, title:'The unfinished dance', kicker:'A MEMORY OF LONGING', color:'#9c6672', note:'A waltz played from a locked gramophone. In the portrait, two figures leaned toward one another but never touched. The painter left the space between them completely bare.', flash:'Wanting is not the same as taking.' },
    { id:'failure', name:'Failure', x:21.7, y:13.8, title:'The room of small names', kicker:'A MEMORY OF FAILURE', color:'#827058', note:'Certificates covered the wallpaper, each one addressed to somebody else. Beneath them, a desk was carved with the same sentence over and over: TRY HARDER. The last line trailed away unfinished.', flash:'I was more than what I could finish.' },
    { id:'depression', name:'The weight', x:5.7, y:4.6, title:'The quiet studio', kicker:'A MEMORY OF DEPRESSION', color:'#657276', note:'A studio left exactly as it was. Brushes hardened in jars. On the easel: a little house under a very large sky. Nothing in the room asked her to get up. Nothing asked her to stay.', flash:'Even the silence has a shape.' }
  ];
  let W=0,H=0,dpr=1, map=[], state='title', player={x:5.2,y:4.3,a:0}, keys={}, mouseDown=false, last=0, exposure=0, active=null, found=new Set(), entities=[], messageTimer=0, noteTarget=null, bob=0, lantern=true, stepClock=0, seen=new Set(), encounterCount=0;
  const FOV=Math.PI/3, TAU=Math.PI*2;
  function buildMap(){
    const w=28,h=19; map=Array.from({length:h},()=>Array(w).fill(1));
    const room=(x1,y1,x2,y2)=>{for(let y=y1;y<=y2;y++)for(let x=x1;x<=x2;x++)map[y][x]=0;};
    const hall=(x1,y1,x2,y2)=>room(x1,y1,x2,y2);
    room(2,2,8,7); room(17,2,24,7); room(2,11,8,16); room(10,9,16,13); room(18,11,25,16);
    hall(8,4,13,4); hall(13,4,17,4); hall(13,4,13,10); hall(5,7,5,11); hall(13,10,13,12); hall(16,11,18,11); hall(13,12,18,12); hall(13,12,13,16); hall(5,11,5,14);
    // Narrow architectural thresholds and recesses.
    map[4][9]=0;map[4][10]=0;map[4][11]=0;map[4][12]=0;map[4][14]=0;map[4][15]=0;map[4][16]=0;
    return map;
  }
  function resize(){dpr=Math.min(devicePixelRatio||1,1.65);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(dpr,0,0,dpr,0,0);}
  addEventListener('resize',resize); resize(); buildMap();
  const memoryDots=$('memory-dots'); memories.forEach(()=>{const s=document.createElement('i');s.className='memory-dot';memoryDots.appendChild(s);});
  function reset(){player={x:5.2,y:4.3,a:0};found.clear();entities=[];active=null;exposure=0;encounterCount=0;lantern=true;state='playing';$('title-screen').hidden=true;$('ending-screen').hidden=true;$('hud').hidden=false;$('reticle').hidden=false;$('controls-hint').hidden=false;$('topbar').hidden=false;updateHUD();say('The canvases are empty. The paint is still wet.');}
  $('begin').addEventListener('click',()=>{reset();canvas.requestPointerLock?.();});
  $('restart').addEventListener('click',()=>{ $('ending-screen').hidden=true; reset(); canvas.requestPointerLock?.(); });
  $('continue').addEventListener('click',()=>closeNote());
  function closeNote(){ $('note-panel').hidden=true; state='playing'; if(noteTarget && !found.has(noteTarget.id)){spawnEntity(noteTarget);active=noteTarget;encounterCount++;say(noteTarget.flash);} noteTarget=null; }
  function updateHUD(){document.querySelectorAll('.memory-dot').forEach((el,i)=>el.classList.toggle('found',found.has(memories[i].id)));$('objective').textContent=found.size===5?'The last portrait is waiting.':'Find what left the canvas.';}
  function say(text){const el=$('message');el.textContent=text;el.hidden=false;el.style.animation='none';void el.offsetWidth;el.style.animation='fade 4.5s both';messageTimer=4.5;}
  function openNote(m){noteTarget=m;state='note';$('note-kicker').textContent=m.kicker;$('note-title').textContent=m.title;$('note-copy').textContent=m.note;$('note-progress').textContent=`FRAGMENT ${found.size+1} / 5`;$('note-panel').hidden=false;document.exitPointerLock?.();}
  function startEnding(){state='ending';document.exitPointerLock?.();$('ending-title').textContent='The last thing she remembers';$('ending-copy').textContent='Five little amber tablets rested in her palm. The room was plain: a chair, a glass of water, a paper cup with her name written carefully across it.\n\nThe house had not been a map of what was wrong with her. It was a map of what she had carried: love that had no place to go, a childhood spent listening, a grief that made ordinary days heavy. The paintings had given those things faces.\n\nBeyond the window, the city glowed without looking back. Somewhere, a clock kept its patient time. She thought of the people who had known her before the rooms grew dark. She thought of the life still waiting in fragments—not fixed, not erased, but hers.\n\nA hand reached for the light. The house, at last, was quiet.\n\nWas this an ending, or simply the moment between one breath and the next?';$('ending-screen').hidden=false;$('hud').hidden=true;$('reticle').hidden=true;$('controls-hint').hidden=true;}
  function spawnEntity(m){entities.push({id:m.id,x:m.x,y:m.y,active:true,phase:Math.random()*5,speed:.48});}
  function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
  function solid(x,y){const ix=Math.floor(x),iy=Math.floor(y);return !map[iy]||map[iy][ix]!==0;}
  function move(dx,dy){if(!solid(player.x+dx*0.22,player.y))player.x+=dx;if(!solid(player.x,player.y+dy*0.22))player.y+=dy;}
  function chooseTarget(){let best=null,bd=2.2;for(const m of memories){if(found.has(m.id))continue;const d=dist(player,m);if(d<bd){bd=d;best=m;}}for(const e of entities){if(e.active){const d=dist(player,e);if(d<1.6){bd=d;best=e;}}}return best;}
  function interact(){if(state!=='playing')return;let target=null;for(const e of entities){if(e.active&&dist(player,e)<1.9){target=e;break;}}if(target){const m=memories.find(x=>x.id===target.id);target.active=false;found.add(m.id);active=null;exposure=Math.max(0,exposure-38);updateHUD();say('A shape settles into the frame.');if(found.size===5)setTimeout(()=>{if(state==='playing')startEnding();},1700);return;}for(const m of memories){if(found.has(m.id))continue;if(dist(player,m)<2.05){openNote(m);return;}}}
  addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='e')interact();if(k==='f'&&state==='playing'){lantern=!lantern;say(lantern?'The lantern steadies.':'Darkness gathers at the edges.');}if(k==='escape'&&state==='playing'){state='paused';$('pause-badge').hidden=false;document.exitPointerLock?.();}});
  addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
  canvas.addEventListener('click',()=>{if(state==='paused'){state='playing';$('pause-badge').hidden=true;canvas.requestPointerLock?.();}});
  document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&state==='playing')player.a+=e.movementX*.0022;});
  function update(dt){if(state!=='playing')return;let forward=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),strafe=(keys.d?1:0)-(keys.a?1:0);if(keys.arrowleft)player.a-=dt*1.8;if(keys.arrowright)player.a+=dt*1.8;const sprint=keys.shift?1.48:1;const len=Math.hypot(forward,strafe)||1;const speed=2.08*sprint*dt;const ca=Math.cos(player.a),sa=Math.sin(player.a);if(forward||strafe){move((ca*forward-sa*strafe)/len*speed,(sa*forward+ca*strafe)/len*speed);bob+=dt*(sprint>1?12:7);stepClock+=dt;if(stepClock>0.42){stepClock=0;if(Math.random()<.24)say('');}}else bob*=.92;
    if(active){let entity=entities.find(e=>e.id===active.id&&e.active);if(entity){const d=dist(player,entity);const ang=Math.atan2(player.y-entity.y,player.x-entity.x);const sp=entity.speed*dt;if(d>1.12){const nx=entity.x+Math.cos(ang)*sp,ny=entity.y+Math.sin(ang)*sp;if(!solid(nx,entity.y))entity.x=nx;if(!solid(entity.x,ny))entity.y=ny;}let rise=(d<7?1.9:0.35)*dt;if(!lantern)rise*=1.33;exposure=Math.min(100,exposure+rise);if(d>8)exposure=Math.max(0,exposure-1.6*dt);if(exposure>=100){state='death';setTimeout(()=>{if(state==='death'){reset();say('The house begins again.');}},900);}}}
    else exposure=Math.max(0,exposure-4.2*dt);
    const exp=$('exposure-fill');exp.style.width=exposure+'%';exp.style.background=exposure>72?'#a4473b':exposure>40?'#ad7652':'#b88c69';$('exposure-state').textContent=exposure>80?'CRITICAL':exposure>55?'OVERWHELMED':exposure>25?'UNSTEADY':'QUIET';if(messageTimer>0){messageTimer-=dt;if(messageTimer<=0)$('message').hidden=true;}
  }
  function wallAt(mx,my){return !map[my]||map[my][mx]!==0;}
  function castRay(angle){let rx=Math.cos(angle),ry=Math.sin(angle),mx=Math.floor(player.x),my=Math.floor(player.y),ddx=Math.abs(1/(rx||.00001)),ddy=Math.abs(1/(ry||.00001)),sx,sy,sdx,sdy,side=0;if(rx<0){sx=-1;sdx=(player.x-mx)*ddx}else{sx=1;sdx=(mx+1-player.x)*ddx}if(ry<0){sy=-1;sdy=(player.y-my)*ddy}else{sy=1;sdy=(my+1-player.y)*ddy}let n=0;while(n++<40){if(sdx<sdy){sdx+=ddx;mx+=sx;side=0}else{sdy+=ddy;my+=sy;side=1}if(wallAt(mx,my))break;}let d=side===0?sdx-ddx:sdy-ddy;let hit=side===0?player.y+d*ry:player.x+d*rx;return {d:Math.max(.05,d*Math.cos(angle-player.a)),side,hit:hit-Math.floor(hit),mx,my};}
  function render(){if(!W||!H)return;ctx.setTransform(dpr,0,0,dpr,0,0);const horizon=H*.49+Math.sin(bob)*1.3;let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,'#100d0d');sky.addColorStop(.72,'#211916');sky.addColorStop(1,'#392820');ctx.fillStyle=sky;ctx.fillRect(0,0,W,horizon);let floor=ctx.createLinearGradient(0,horizon,0,H);floor.addColorStop(0,'#251b16');floor.addColorStop(.35,'#171211');floor.addColorStop(1,'#080707');ctx.fillStyle=floor;ctx.fillRect(0,horizon,W,H-horizon);
    // worn floorboards recede toward a vanishing point
    ctx.save();ctx.globalAlpha=.12;ctx.strokeStyle='#a5815f';ctx.lineWidth=1;for(let i=1;i<13;i++){let t=i/13,y=horizon+(H-horizon)*t*t;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}for(let x=0;x<W;x+=105){ctx.beginPath();ctx.moveTo(W/2+(x-W/2)*.08,horizon);ctx.lineTo(x,H);ctx.stroke();}ctx.restore();
    const rays=Math.ceil(W/2.5),colW=W/rays;for(let i=0;i<rays;i++){const a=player.a-FOV/2+(i/rays)*FOV;const hit=castRay(a),d=hit.d;const wh=Math.min(H*2,H*.92/d);const top=horizon-wh/2;let sideShade=hit.side?.72:1;let stripe=Math.floor(hit.hit*12)%2?.92:1;const fog=Math.max(.08,1-d/14);let r=55*sideShade*stripe*fog+10,g=39*sideShade*stripe*fog+8,b=32*sideShade*stripe*fog+7;ctx.fillStyle=`rgb(${r|0},${g|0},${b|0})`;ctx.fillRect(i*colW,top,colW+1,wh);if((Math.floor(hit.hit*8)===0)&&d<8){ctx.fillStyle=`rgba(177,134,91,${.13*fog})`;ctx.fillRect(i*colW,top,colW+1,wh);} // wall seams
      if(hit.hit<.025||hit.hit>.975){ctx.fillStyle=`rgba(8,6,6,${.38*fog})`;ctx.fillRect(i*colW,top,colW+1,wh);}const shade=ctx.createLinearGradient(0,top,0,top+wh);shade.addColorStop(0,'rgba(0,0,0,.4)');shade.addColorStop(.5,'rgba(0,0,0,0)');shade.addColorStop(1,'rgba(0,0,0,.5)');ctx.fillStyle=shade;ctx.fillRect(i*colW,top,colW+1,wh);
      // soft amber lantern pool
      if(lantern){const center=Math.abs(i/rays-.5);if(center<.28&&d<7){ctx.fillStyle=`rgba(176,117,60,${(1-center/.28)*.045*(1-d/8)})`;ctx.fillRect(i*colW,top,colW+1,wh);}}
    }
    drawFixtures();drawEntities();if(exposure>15){ctx.fillStyle=`rgba(89,22,25,${Math.min(.2,(exposure-15)/500)})`;ctx.fillRect(0,0,W,H);const amp=exposure/100*4;ctx.fillStyle=`rgba(160,115,131,${exposure/600})`;ctx.fillRect(Math.random()*amp-amp/2,0,W,H);} // peripheral hallucination haze
    if(state==='death'){ctx.fillStyle='rgba(10,5,7,.16)';ctx.fillRect(0,0,W,H);}
  }
  function project(x,y){const dx=x-player.x,dy=y-player.y,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx)-player.a;let rel=((a+Math.PI*3)%(TAU))-Math.PI;return {sx:W/2+Math.tan(rel)*(W*.77),d,rel};}
  function drawFixtures(){const items=memories.map(m=>({...m,type:'painting'})); // chandelier glints in the hall
    for(let x=4;x<25;x+=4)items.push({type:'lamp',x:x,y:4.2});
    items.sort((a,b)=>dist(player,b)-dist(player,a));for(const o of items){const p=project(o.x,o.y);if(p.d>.5&&p.d<11&&Math.abs(p.rel)<.9){const scale=Math.min(H*.72,H*.64/p.d),x=p.sx;if(o.type==='lamp'){drawLamp(x,H*.24,scale*.23,p.d);continue;}drawPainting(x,H*.48,scale*.45,o,p.d);}}
  }
  function drawLamp(x,y,s,d){const w=s*.64,h=s*.53;ctx.save();ctx.globalAlpha=Math.max(.25,1-d/12);ctx.strokeStyle='#8c6b48';ctx.lineWidth=Math.max(1,s*.016);ctx.beginPath();ctx.moveTo(x,y-h*.8);ctx.lineTo(x,y-h*.25);ctx.stroke();ctx.fillStyle='rgba(220,162,91,.18)';ctx.beginPath();ctx.ellipse(x,y,s*.7,s*.7,0,0,TAU);ctx.fill();ctx.fillStyle='#775334';ctx.beginPath();ctx.moveTo(x-w/2,y-h*.25);ctx.lineTo(x+w/2,y-h*.25);ctx.lineTo(x+w*.35,y+h*.35);ctx.lineTo(x-w*.35,y+h*.35);ctx.closePath();ctx.fill();ctx.strokeStyle='#c19a68';ctx.stroke();for(let i=-1;i<=1;i++){ctx.fillStyle='#e5b775';ctx.beginPath();ctx.ellipse(x+i*w*.25,y+h*.25,Math.max(1,s*.027),Math.max(2,s*.065),0,0,TAU);ctx.fill();}ctx.restore();}
  function drawPainting(x,y,s,m,d){const w=s*.55,h=s*.76;ctx.save();ctx.globalAlpha=Math.min(1,1-d/12);ctx.shadowColor='#d49b5b';ctx.shadowBlur=Math.max(0,(8-d)*2);ctx.fillStyle='#4b321f';ctx.fillRect(x-w/2-5,y-h/2-5,w+10,h+10);ctx.shadowBlur=0;ctx.strokeStyle='#b88d55';ctx.lineWidth=Math.max(1,s*.035);ctx.strokeRect(x-w/2,y-h/2,w,h);ctx.strokeStyle='#6b5030';ctx.lineWidth=Math.max(1,s*.017);ctx.strokeRect(x-w/2+4,y-h/2+4,w-8,h-8);const grad=ctx.createLinearGradient(x,y-h/2,x,y+h/2);grad.addColorStop(0,'#241e1b');grad.addColorStop(1,'#171514');ctx.fillStyle=grad;ctx.fillRect(x-w/2+8,y-h/2+8,w-16,h-16);if(!found.has(m.id)){ctx.strokeStyle=m.color;ctx.globalAlpha*=.35;ctx.lineWidth=Math.max(1,s*.018);ctx.beginPath();ctx.moveTo(x-w*.18,y+h*.19);ctx.bezierCurveTo(x-w*.05,y-h*.16,x+w*.16,y-h*.12,x+w*.2,y+h*.1);ctx.stroke();}ctx.restore();}
  function drawEntities(){const visible=entities.filter(e=>e.active).sort((a,b)=>dist(player,b)-dist(player,a));for(const e of visible){const p=project(e.x,e.y);if(p.d>.25&&p.d<13&&Math.abs(p.rel)<1){const sc=Math.min(H*.9,H*.68/p.d);drawCreature(p.sx,H*.5+Math.sin(performance.now()/420+e.phase)*sc*.025,sc,e,exposure);}}}
  function drawCreature(x,y,s,e,exp){const color={regret:'#8b624c',fear:'#7c898c',desire:'#96636b',failure:'#82775f',depression:'#5d6b70'}[e.id]||'#777';const w=s*.36,h=s*.74;ctx.save();ctx.translate(x,y);ctx.globalAlpha=Math.min(.94,.48+exp/180);ctx.shadowColor=color;ctx.shadowBlur=s*.12;ctx.fillStyle=color;ctx.strokeStyle='rgba(210,186,154,.55)';ctx.lineWidth=Math.max(1,s*.012);
    if(e.id==='regret'){ // a folded figure with too many reaching arms
      ctx.beginPath();ctx.moveTo(-w*.1,-h*.35);ctx.quadraticCurveTo(-w*.62,-h*.12,-w*.22,h*.43);ctx.quadraticCurveTo(0,h*.54,w*.3,h*.39);ctx.quadraticCurveTo(w*.44,-h*.06,w*.08,-h*.35);ctx.closePath();ctx.fill();for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(-w*.12+i*w*.07,-h*.12);ctx.lineTo(-w*(.74+i*.05),h*(.06+i*.05));ctx.stroke();}ctx.fillStyle='#d2aa70';ctx.beginPath();ctx.ellipse(w*.02,-h*.24,w*.04,h*.025,0,0,TAU);ctx.fill();}
    else if(e.id==='fear'){ctx.beginPath();ctx.ellipse(0,-h*.18,w*.35,h*.26,0,0,TAU);ctx.fill();ctx.beginPath();ctx.moveTo(-w*.3,-h*.04);ctx.lineTo(-w*.52,h*.45);ctx.lineTo(w*.48,h*.45);ctx.lineTo(w*.28,-h*.04);ctx.fill();for(let i=-2;i<=2;i++){ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(i*w*.11,-h*.4);ctx.lineTo(i*w*.28,-h*.55);ctx.stroke();}ctx.fillStyle='#e1d3bb';ctx.beginPath();ctx.ellipse(0,-h*.2,w*.18,h*.035,0,0,TAU);ctx.fill();}
    else if(e.id==='desire'){ctx.beginPath();ctx.moveTo(0,-h*.42);ctx.bezierCurveTo(w*.75,-h*.23,w*.42,h*.05,0,h*.42);ctx.bezierCurveTo(-w*.42,h*.05,-w*.75,-h*.23,0,-h*.42);ctx.fill();ctx.strokeStyle='#d0a6a0';ctx.beginPath();ctx.arc(0,0,w*.28,0,TAU);ctx.stroke();ctx.fillStyle='#241719';ctx.beginPath();ctx.arc(0,0,w*.17,0,TAU);ctx.fill();}
    else if(e.id==='failure'){ctx.beginPath();ctx.moveTo(-w*.35,-h*.25);ctx.lineTo(w*.36,-h*.25);ctx.lineTo(w*.24,h*.32);ctx.lineTo(0,h*.45);ctx.lineTo(-w*.25,h*.3);ctx.closePath();ctx.fill();for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(i*w*.18,-h*.2);ctx.lineTo(i*w*.12,-h*.46);ctx.stroke();}ctx.fillStyle='#211c17';ctx.fillRect(-w*.24,-h*.08,w*.48,h*.06);}
    else {ctx.beginPath();ctx.ellipse(0,h*.12,w*.48,h*.41,0,0,TAU);ctx.fill();ctx.beginPath();ctx.ellipse(0,-h*.19,w*.29,h*.27,0,0,TAU);ctx.fill();ctx.strokeStyle='rgba(27,31,31,.65)';ctx.lineWidth=Math.max(2,s*.04);for(let i=-2;i<=2;i++){ctx.beginPath();ctx.moveTo(i*w*.12,h*.08);ctx.lineTo(i*w*.1,h*.42);ctx.stroke();}ctx.fillStyle='#161b1b';ctx.fillRect(-w*.17,-h*.2,w*.34,h*.025);}
    ctx.restore();}
  function frame(t){const dt=Math.min(.05,(t-last)/1000||0);last=t;update(dt);render();requestAnimationFrame(frame);}requestAnimationFrame(frame);
  // Pointer lock is optional: keyboard turning remains available on touchpads and browsers that deny it.
  $('pause-badge').addEventListener('click',()=>{if(state==='paused'){state='playing';$('pause-badge').hidden=true;}});
  // Focus the game surface for keyboard controls.
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing'){state='paused';$('pause-badge').hidden=false;}});
})();

